css:
.p10-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p10-page > .deck, .p10-page > .p10-center { grid-row: 2; align-self: center; }
.p10-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p10-top:empty { display: none; }
.p10-strip { --p10-strip-h: 9.5rem; }
.p10-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p10-strip-h)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p10-strip { --p10-strip-h: 19.5rem; } }
@media (max-width: 21.25rem) { .p10-strip { --p10-strip-h: 29.5rem; } }
.p10-scrolled .p10-page { margin-top: -5.25rem; }
.p10-e { --frame-w: var(--w2); }
.p10-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p10-w { position: relative; display: inline-grid; }
.p10-tipw { position: relative; display: inline-flex; }
.p10-tip-up { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); left: 50%; translate: -50% 0; width: max-content; max-width: min(17.5rem, 80vw); text-align: center; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p10-tip-up.p10-tip-start { left: 0; translate: 0 0; text-align: start; }
  .p10-tip-up.p10-tip-end { left: auto; right: 0; translate: 0 0; text-align: end; }
}
.p10-tip-dn { position: absolute; z-index: 30; top: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }

.deck-card__foot.p-solo > :first-child { justify-self: center; }

.p10-pressed { border: var(--w2) solid var(--ink); }
.p10-fly { transform: translateX(62%); }
.p10-single .deck__stack { height: var(--card); }
.p10-scroll { border-bottom: var(--w1) solid var(--rule); scrollbar-width: thin; scrollbar-color: var(--line) transparent; }
.p10-fcenter { align-items: center; justify-content: center; text-align: center; }
.p10-cs { display: grid; justify-items: center; gap: var(--s-3); }
.p10-cs .banner { justify-content: center; }
.p10-empty { display: grid; gap: var(--s-3); justify-items: stretch; max-width: 40rem; margin-inline: auto; padding: var(--s-4) var(--s-3); }
.p10-empty .prose { display: grid; gap: var(--s-3); }
.p10-empty .deck__actions { width: min(100%, 24rem); justify-self: center; }
.p10-status { display: flex; align-items: center; justify-content: center; gap: var(--s-2); padding: var(--s-5) var(--s-3); }
.p10-err { display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; margin-inline: auto; padding: var(--s-4) var(--s-3); }
.p10-err .banner { width: 100%; }
.p10-page.p10-msg { display: block; }
.p10-scrolled .p10-page { margin-top: -13rem; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .deck__actions > .p10-tipw { display: contents; }
  .deck__actions > .p10-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }
}
.p10-strip.p10-strip--b { --p10-strip-h: 8rem; }
@media (max-width: 21.25rem) { .p10-strip.p10-strip--b { --p10-strip-h: 8rem; } }

.deck-card:has(.deck-card__foot > .flag) .deck-card__face--front .deck-card__text.p10-scroll { flex: none; margin-bottom: 0; --p10-tl: 3; height: max(1lh, calc(var(--card) * 0.56 - var(--pad) - var(--p10-tl) * var(--lh-h1) - var(--s-1) - 2 * var(--s-2))); }   
@supports (height: round(down, 1px, 1px)) { .deck-card:has(.deck-card__foot > .flag) .deck-card__face--front .deck-card__text.p10-scroll { height: max(1lh, round(down, calc(var(--card) * 0.56 - var(--pad) - var(--p10-tl) * var(--lh-h1) - var(--s-1) - 2 * var(--s-2)), 1lh)); } }
@container card (max-width: 18.74rem) {
  .deck-card:has(.deck-card__foot > .flag) .deck-card__face--front .deck-card__text.p10-scroll { --p10-tl: 2; height: max(1lh, calc(var(--card) * 0.5 - var(--pad) - var(--p10-tl) * var(--lh-h1) - var(--s-1) - 2 * var(--s-2))); }   
  @supports (height: round(down, 1px, 1px)) { .deck-card:has(.deck-card__foot > .flag) .deck-card__face--front .deck-card__text.p10-scroll { height: max(1lh, round(down, calc(var(--card) * 0.5 - var(--pad) - var(--p10-tl) * var(--lh-h1) - var(--s-1) - 2 * var(--s-2)), 1lh)); } }
}
